effect.shader:
void main(){
    vec2 src = source/1000.0 + 0.5;
    vec2 uv = acScreenNorm;
    vec2 delta = (uv - src) * density * 0.04;
    vec4 base = texture2DCv(inputImg.texture, uv);
    vec3 accum = vec3(0.0);
    float illum = 1.0;
    vec2 coord = uv;
    for(int i=0;i<32;i++){
        coord -= delta;
        vec4 s = texture2DCv(inputImg.texture, coord);
        float l = dot(s.rgb, vec3(0.299,0.587,0.114));
        accum += l * illum * color.rgb;
        illum *= decay;
    }
    accum *= weight*0.15;
    vec3 outc = base.rgb + accum;
    gl_FragColor = vec4(outc, base.a) + vec4(accum,0.0)*(1.0-base.a);
}
